	mst.rad_item_info->3->>''item_class'' as item_class4,
  mst.rad_item_info->4->>''ctl_name'' as ctl_name5,
  mst.rad_item_info->4->>''item_cd'' as item_cd5,
	mst.rad_item_info->4->>''item_class'' as item_class5,
  mst.rad_item_info->5->>''ctl_name'' as ctl_name6,
  mst.rad_item_info->5->>''item_cd'' as item_cd6,
	mst.rad_item_info->5->>''item_class'' as item_class6,
	mst.rad_item_info->6->>''ctl_name'' as ctl_name7,
  mst.rad_item_info->6->>''item_cd'' as item_cd7,
	mst.rad_item_info->6->>''item_class'' as item_class7,
	mst.rad_item_info->7->>''ctl_name'' as ctl_name8,
  mst.rad_item_info->7->>''item_cd'' as item_cd8,
	mst.rad_item_info->7->>''item_class'' as item_class8,
