	mst.rad_item_info->9->>''ctl_name'' as ctl_name10,
  mst.rad_item_info->9->>''item_cd'' as item_cd10,
	mst.rad_item_info->9->>''item_class'' as item_class10,
	mst.rad_item_info->10->>''ctl_name'' as ctl_name11,
  mst.rad_item_info->10->>''item_cd'' as item_cd11,
	mst.rad_item_info->10->>''item_class'' as item_class11,
	mst.rad_item_info->11->>''ctl_name'' as ctl_name12,
  mst.rad_item_info->11->>''item_cd'' as item_cd12,
	mst.rad_item_info->11->>''item_class'' as item_class12,
	mst.rad_item_info->12->>''ctl_name'' as ctl_name13,
  mst.rad_item_info->12->>''item_cd'' as item_cd13,
	mst.rad_item_info->12->>''item_class'' as item_class13,
	mst.rad_item_info->13->>''ctl_name'' as ctl_name14,
  mst.rad_item_info->13->>''item_cd'' as item_cd14,
	mst.rad_item_info->13->>''item_class'' as item_class14,
	mst.rad_item_info->14->>''ctl_name'' as ctl_name15,
  mst.rad_item_info->14->>''item_cd'' as item_cd15,
	mst.rad_item_info->14->>''item_class'' as item_class15,
	mst.rad_item_info->15->>''ctl_name'' as ctl_name16,
  mst.rad_item_info->15->>''item_cd'' as item_cd16,
	mst.rad_item_info->15->>''item_class'' as item_class16,
	mst.rad_item_info->16->>''ctl_name'' as ctl_name17,
  mst.rad_item_info->16->>''item_cd'' as item_cd17,
	mst.rad_item_info->16->>''item_class'' as item_class17,
	mst.rad_item_info->17->>''ctl_name'' as ctl_name18,
  mst.rad_item_info->17->>''item_cd'' as item_cd18,
	mst.rad_item_info->17->>''item_class'' as item_class18,
	mst.rad_item_info->18->>''ctl_name'' as ctl_name19,
  mst.rad_item_info->18->>''item_cd'' as item_cd19,
	mst.rad_item_info->18->>''item_class'' as item_class19,
	mst.rad_item_info->19->>''ctl_name'' as ctl_name20,
  mst.rad_item_info->19->>''item_cd'' as item_cd20,
	mst.rad_item_info->19->>''item_class'' as item_class20,
  mst.in_hospital_cd1 as in_hospital_cd1,
  mst.in_hospital_cd2 as in_hospital_cd2,
  mst.in_hospital_cd3 as in_hospital_cd3,
  mst.sbt_cd1 as sbt_cd1,
  mst.sbt_cd2 as sbt_cd2,
  mst.sbt_cd3 as sbt_cd3
from(
  select
   m.*
  from
    pat_rad_main as m
  where
    m.is_del = ''0''
    and jsonb_array_length(m.order_rad_set_info) > 0
    and m.pat_id IN (@patIds)
    and m.reg_rad_date >= date_trunc(''day'', @date ::timestamp )
    order by m.reg_rad_date
    ) p
  cross join lateral
    json_array_elements (p.order_rad_set_info :: json) info
  left outer join
    mst_rad_set as mst on info->>''rad_set_cd'' = (mst.rad_set_cd || '''') and mst.is_del = ''0'' and mst.is_disp = ''1''
  limit 100
